CREATE TABLE IF NOT EXISTS students (id SERIAL PRIMARY KEY, username VARCHAR UNIQUE NOT NULL, password VARCHAR NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notes (id SERIAL PRIMARY KEY, student_id INT REFERENCES students(id) ON DELETE CASCADE, title VARCHAR NOT NULL, subject VARCHAR, raw_content TEXT NOT NULL, summary TEXT, key_points JSONB, definitions JSONB, flowchart_mermaid TEXT, mindmap_mermaid TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quizzes (id SERIAL PRIMARY KEY, note_id INT REFERENCES notes(id) ON DELETE CASCADE, student_id INT REFERENCES students(id) ON DELETE CASCADE, questions JSONB NOT NULL, flashcards JSONB NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quiz_attempts (id SERIAL PRIMARY KEY, quiz_id INT REFERENCES quizzes(id) ON DELETE CASCADE, student_id INT REFERENCES students(id) ON DELETE CASCADE, score INT NOT NULL, total_questions INT NOT NULL, wrong_answers JSONB, attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge_gaps (id SERIAL PRIMARY KEY, student_id INT REFERENCES students(id) ON DELETE CASCADE, note_id INT REFERENCES notes(id) ON DELETE CASCADE, weak_topic VARCHAR NOT NULL, status VARCHAR DEFAULT 'needs_practice', simple_explanation TEXT, recommended_action TEXT, mini_flowchart TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS revision_plans (id SERIAL PRIMARY KEY, student_id INT REFERENCES students(id) ON DELETE CASCADE, exam_date DATE NOT NULL, daily_hours INT DEFAULT 2, schedule JSONB NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chat_messages (id SERIAL PRIMARY KEY, student_id INT REFERENCES students(id) ON DELETE CASCADE, note_id INT REFERENCES notes(id) ON DELETE CASCADE, role VARCHAR NOT NULL, message TEXT NOT NULL, source_reference VARCHAR, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
